package java.util.concurrent.locks;
import java.util.concurrent.TimeUnit;
public class StampedLock implements java.io.Serializable {private long version=256;private boolean write;private int reads;public long writeLock(){if(write||reads>0){java.lang.VMThread.runPending();if(write||reads>0)throw new IllegalStateException();}write=true;return version+1;}public long tryWriteLock(){return write||reads>0?0:writeLock();}public long tryWriteLock(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return tryWriteLock();}public long writeLockInterruptibly()throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();return writeLock();}public long readLock(){reads++;return version+2;}public long tryReadLock(){return write?0:readLock();}public long tryReadLock(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return tryReadLock();}public long readLockInterruptibly()throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();return readLock();}public long tryOptimisticRead(){return write?0:version;}public boolean validate(long s){return s!=0&&!write&&(s&~255L)==version;}public void unlockWrite(long s){if(!write||s!=version+1)throw new IllegalMonitorStateException();write=false;version+=256;}public void unlockRead(long s){if(reads==0||s!=version+2)throw new IllegalMonitorStateException();reads--;}public void unlock(long s){if((s&255)==1)unlockWrite(s);else unlockRead(s);}public boolean isWriteLocked(){return write;}public boolean isReadLocked(){return reads>0;}public int getReadLockCount(){return reads;}}
